package com.agriconnect.controller; import com.agriconnect.model.AppUser; import com.agriconnect.service.AuthService; import jakarta.servlet.http.HttpSession; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.support.RedirectAttributes; @Controller public class AuthController {private final AuthService a; public AuthController(AuthService a){this.a=a;} @GetMapping("/register") public String reg(Model m){m.addAttribute("user",new AppUser());return "register";} @PostMapping("/register") public String reg(@ModelAttribute AppUser u,@RequestParam String confirmPassword,Model m,RedirectAttributes r){if(u.getPassword()==null||u.getPassword().length()<6||!u.getPassword().equals(confirmPassword)){m.addAttribute("error","Passwords must match and contain at least 6 characters.");return "register";}try{a.register(u);r.addFlashAttribute("success","Account created. Please log in.");return "redirect:/login";}catch(Exception e){m.addAttribute("error",e.getMessage());return "register";}} @GetMapping("/login") public String login(){return "login";} @PostMapping("/login") public String login(@RequestParam String email,@RequestParam String password,HttpSession s,Model m){AppUser u=a.login(email,password);if(u==null){m.addAttribute("error","Invalid email or password.");return "login";}s.setAttribute("user",u);return "redirect:/dashboard";} @PostMapping("/logout") public String logout(HttpSession s){s.invalidate();return "redirect:/";}}